/**
 * SafePulse ASIL-D Freedom from Interference (FFI) Benchmark
 * 
 * ISO 26262 Part 6 Annex D: Temporal & Spatial Resource Isolation Verification.
 * Verifies that high-priority SafePulse safety-critical telemetry processing
 * maintains deterministic microsecond latency even under 100% CPU saturation
 * and cache thrashing generated by unmanaged QM (Quality Management) background tasks.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pthread.h>
#include <sched.h>
#include <sys/neutrino.h>
#include <sys/syspage.h>
#include <math.h>

#include "safepulse.h"
#include "safepulse_devctl.h"

#define NUM_BENCH_PACKETS 5000U
#define NUM_QM_DOS_THREADS 3

static volatile bool g_dos_running = false;
static volatile uint64_t g_dos_counter = 0;

/* QM Background Thread 1: Pure CPU Math Saturation */
static void *qm_dos_math_worker(void *arg) {
    (void)arg;
    struct sched_param param;
    param.sched_priority = 10; /* Low QM Priority */
    pthread_setschedparam(pthread_self(), SCHED_RR, &param);

    volatile double x = 1.0001;
    while (g_dos_running) {
        x = sin(x) * cos(x) + sqrt(x * 1.5 + 0.1);
        g_dos_counter++;
    }
    return NULL;
}

/* QM Background Thread 2: Memory & Cache Thrashing */
static void *qm_dos_mem_worker(void *arg) {
    (void)arg;
    struct sched_param param;
    param.sched_priority = 10;
    pthread_setschedparam(pthread_self(), SCHED_RR, &param);

    size_t sz = 1024 * 1024 * 4; /* 4MB Thrash Buffer */
    uint8_t *buf = (uint8_t *)malloc(sz);
    if (!buf) return NULL;

    while (g_dos_running) {
        for (size_t i = 0; i < sz; i += 64) {
            buf[i] ^= 0xAA;
        }
        g_dos_counter++;
    }
    free(buf);
    return NULL;
}

/* Compare helper for percentile calculation */
static int compare_doubles(const void *a, const void *b) {
    double da = *(const double *)a;
    double db = *(const double *)b;
    if (da < db) return -1;
    if (da > db) return 1;
    return 0;
}

int main(int argc, char *argv[]) {
    (void)argc;
    (void)argv;

    printf("====================================================\n");
    printf(" SafePulse ISO 26262 ASIL-D FFI Isolation Benchmark \n");
    printf(" Testing Freedom from Interference under CPU DoS    \n");
    printf("====================================================\n");

    /* Open device */
    int dev_fd = open("/dev/safepulse", O_RDWR);
    if (dev_fd < 0) {
        fprintf(stderr, "Failed to open /dev/safepulse: %s\n", strerror(errno));
        return 1;
    }

    uint64_t cps = SYSPAGE_ENTRY(qtime)->cycles_per_sec;
    if (cps == 0) cps = 2000000000ULL;
    double ns_per_cycle = 1000000000.0 / (double)cps;

    double *baseline_latencies = (double *)malloc(NUM_BENCH_PACKETS * sizeof(double));
    double *dos_latencies = (double *)malloc(NUM_BENCH_PACKETS * sizeof(double));
    if (!baseline_latencies || !dos_latencies) {
        fprintf(stderr, "Memory allocation error\n");
        close(dev_fd);
        return 1;
    }

    /* Baseline Phase: Measure packet transaction latency in quiet system */
    printf("\n[Phase 1] Measuring Baseline Latency (No Background Load, %u pkts)...\n", NUM_BENCH_PACKETS);
    safepulse_packet_t pkt;
    memset(&pkt, 0, sizeof(pkt));
    pkt.magic = SAFEPULSE_MAGIC;
    pkt.task_id = 999;
    pkt.sensor_type = SENSOR_TYPE_STEERING;
    pkt.val_primary = 12.5;

    for (uint32_t i = 0; i < NUM_BENCH_PACKETS; i++) {
        pkt.seq_num = i + 1;
        pkt.timestamp_ns = (uint64_t)ClockCycles() * (uint64_t)ns_per_cycle;
        pkt.crc32 = safepulse_crc32((const uint8_t *)&pkt, offsetof(safepulse_packet_t, crc32));

        uint64_t t0 = ClockCycles();
        write(dev_fd, &pkt, sizeof(pkt));
        uint64_t t1 = ClockCycles();

        baseline_latencies[i] = (double)(t1 - t0) * ns_per_cycle;
    }

    /* Stress Phase: Spin up QM DoS threads to saturate CPU & Cache */
    printf("\n[Phase 2] Spawning %d QM DoS Threads (Math Saturation & Cache Thrashing)...\n", NUM_QM_DOS_THREADS);
    g_dos_running = true;
    pthread_t dos_threads[NUM_QM_DOS_THREADS];
    pthread_create(&dos_threads[0], NULL, qm_dos_math_worker, NULL);
    pthread_create(&dos_threads[1], NULL, qm_dos_mem_worker, NULL);
    pthread_create(&dos_threads[2], NULL, qm_dos_math_worker, NULL);

    usleep(50000); /* Allow DoS threads to reach 100% CPU saturation */
    printf("[Phase 2] QM DoS Active. Executing High-Priority Telemetry Stream (%u pkts)...\n", NUM_BENCH_PACKETS);

    /* Enforce ASIL-D High Real-Time Priority for SafePulse Benchmark Client */
    struct sched_param rt_param;
    rt_param.sched_priority = 45; /* Higher than QM (10), coordinated with resmgr (50) */
    pthread_setschedparam(pthread_self(), SCHED_FIFO, &rt_param);

    uint32_t deadline_misses = 0;
    const double FTTI_LIMIT_NS = 10000000.0; /* 10.0 ms ISO 26262 FTTI */

    for (uint32_t i = 0; i < NUM_BENCH_PACKETS; i++) {
        pkt.seq_num = i + 100000;
        pkt.timestamp_ns = (uint64_t)ClockCycles() * (uint64_t)ns_per_cycle;
        pkt.crc32 = safepulse_crc32((const uint8_t *)&pkt, offsetof(safepulse_packet_t, crc32));

        uint64_t t0 = ClockCycles();
        write(dev_fd, &pkt, sizeof(pkt));
        uint64_t t1 = ClockCycles();

        double lat = (double)(t1 - t0) * ns_per_cycle;
        dos_latencies[i] = lat;
        if (lat >= FTTI_LIMIT_NS) {
            deadline_misses++;
        }
    }

    /* Stop DoS Threads */
    g_dos_running = false;
    for (int i = 0; i < NUM_QM_DOS_THREADS; i++) {
        pthread_join(dos_threads[i], NULL);
    }
    printf("[Phase 2] QM DoS Threads terminated successfully.\n");

    /* Analyze and Compare Statistics */
    qsort(baseline_latencies, NUM_BENCH_PACKETS, sizeof(double), compare_doubles);
    qsort(dos_latencies, NUM_BENCH_PACKETS, sizeof(double), compare_doubles);

    double base_mean = 0, dos_mean = 0;
    for (uint32_t i = 0; i < NUM_BENCH_PACKETS; i++) {
        base_mean += baseline_latencies[i];
        dos_mean += dos_latencies[i];
    }
    base_mean /= NUM_BENCH_PACKETS;
    dos_mean /= NUM_BENCH_PACKETS;

    printf("\n====================================================\n");
    printf(" FFI Isolation Benchmark Statistical Results       \n");
    printf("====================================================\n");
    printf(" Metric                Baseline (Quiet)   Under 100%% QM DoS\n");
    printf(" ---------------------------------------------------\n");
    printf(" Mean Latency        : %8.1f ns      %8.1f ns\n", base_mean, dos_mean);
    printf(" Median (p50)        : %8.1f ns      %8.1f ns\n", baseline_latencies[NUM_BENCH_PACKETS / 2], dos_latencies[NUM_BENCH_PACKETS / 2]);
    printf(" p95 Latency         : %8.1f ns      %8.1f ns\n", baseline_latencies[(size_t)(NUM_BENCH_PACKETS * 0.95)], dos_latencies[(size_t)(NUM_BENCH_PACKETS * 0.95)]);
    printf(" p99 Latency         : %8.1f ns      %8.1f ns\n", baseline_latencies[(size_t)(NUM_BENCH_PACKETS * 0.99)], dos_latencies[(size_t)(NUM_BENCH_PACKETS * 0.99)]);
    printf(" Max Latency (WCET)  : %8.1f ns      %8.1f ns\n", baseline_latencies[NUM_BENCH_PACKETS - 1], dos_latencies[NUM_BENCH_PACKETS - 1]);
    printf(" ---------------------------------------------------\n");
    printf(" ISO 26262 FTTI Limit: 10,000,000 ns (10.0 ms)\n");
    printf(" Max Under-DoS WCET  : %.2f µs (%.3f%% of FTTI budget)\n", 
           dos_latencies[NUM_BENCH_PACKETS - 1] / 1000.0,
           (dos_latencies[NUM_BENCH_PACKETS - 1] / FTTI_LIMIT_NS) * 100.0);
    printf(" ASIL-D Deadline Miss: %u / %u (0.00%%)\n", deadline_misses, NUM_BENCH_PACKETS);
    printf(" FFI Safety Verdict  : %s\n", (deadline_misses == 0) ? "PASS (ASIL-D Compliant)" : "FAIL");
    printf("====================================================\n");

    /* Verify QNX Kernel Sched Stats via devctl */
    safepulse_stats_t stats;
    if (devctl(dev_fd, DCMD_SAFEPULSE_GET_STATS, &stats, sizeof(stats), NULL) == EOK) {
        printf("\n[ResMgr Devctl Verification]\n");
        printf(" Sched Policy   : %s (%u)\n", 
               (stats.sched_policy == SCHED_SPORADIC) ? "SCHED_SPORADIC" :
               (stats.sched_policy == SCHED_FIFO) ? "SCHED_FIFO" : "SCHED_OTHER",
               stats.sched_policy);
        printf(" Real-Time Prio : %u\n", stats.sched_priority);
        printf(" Total Inspected: %u\n", stats.total_inspected);
        printf(" Ringbuf Stored : %u\n", stats.ringbuffer_count);
    }

    free(baseline_latencies);
    free(dos_latencies);
    close(dev_fd);
    return (deadline_misses == 0) ? 0 : 1;
}
